require 'json'
require 'securerandom'
require 'bcrypt'

module MessageQueue
  ALLOWED_HANDLER_MODULES = %w[Handlers::Billing Handlers::Notifications Handlers::Analytics Handlers::Reports].freeze
  ROLE_PERMISSIONS = {
    'admin' => %w[billing notifications analytics reports system],
    'manager' => %w[billing notifications analytics reports],
    'worker' => %w[notifications analytics],
    'viewer' => %w[analytics]
  }.freeze

  class AccessControl
    def initialize(user_role)
      @role = user_role
      @permissions = ROLE_PERMISSIONS.fetch(@role, [])
    end

    def authorized?(action_domain)
      @permissions.include?(action_domain.to_s.downcase)
    end

    def role
      @role
    end
  end

  class HandlerRegistry
    def initialize
      @registry = {}
      @module_whitelist = ALLOWED_HANDLER_MODULES.map(&:downcase)
    end

    def register(name, klass)
      @registry[name.to_s] = klass
    end

    def resolve(handler_name)
      @registry[handler_name.to_s]
    end

    def safe_module?(qualified_name)
      @module_whitelist.any? { |prefix| qualified_name.downcase.start_with?(prefix) }
    end
  end

  class MessageConsumer
    def initialize(registry, logger: nil)
      @registry = registry
      @logger = logger || method(:default_log)
    end

    def process(raw_message, access_control)
      message = parse_message(raw_message)
      return { error: 'invalid message format' } unless message

      handler_ref = message['handler']
      method_name = message['action']
      payload = message['payload'] || {}
      domain = message['domain']

      unless access_control.authorized?(domain)
        @logger.call("ACCESS DENIED: role=#{access_control.role} domain=#{domain}")
        return { error: 'access denied' }
      end

      handler_class = resolve_handler(handler_ref, access_control)
      return { error: 'handler not found or not permitted' } unless handler_class

      execute_action(handler_class, method_name, payload)
    end

    private

    def parse_message(raw)
      JSON.parse(raw)
    rescue JSON::ParserError
      nil
    end

    def resolve_handler(handler_ref, access_control)
      # First try the registry for pre-registered handlers
      registered = @registry.resolve(handler_ref)
      return registered if registered

      # Dynamic resolution with safety checks
      return nil unless valid_handler_name?(handler_ref)

      resolved_class = safe_constantize(handler_ref)
      return nil unless resolved_class

      # Verify the resolved class is in our allowed module list
      qualified = resolved_class.name
      return nil unless @registry.safe_module?(qualified)

      resolved_class
    end

    def valid_handler_name?(name)
      # Only allow names that look like Ruby constants with :: separators
      name.match?(/\A[A-Z][A-Za-z0-9]*(::[A-Z][A-Za-z0-9]*)*\z/)
    end

    def safe_constantize(name)
      parts = name.split('::')
      parts.reduce(Object) do |mod, const_name|
        return nil unless mod.const_defined?(const_name, false)
        mod.const_get(const_name, false)
      end
    rescue NameError
      nil
    end

    def execute_action(handler_class, method_name, payload)
      # Validate method name format
      return { error: 'invalid action' } unless method_name.match?(/\A[a-z_][a-z0-9_]*\z/)

      instance = handler_class.new

      # Only call methods defined directly on the handler class
      unless handler_class.public_instance_methods(false).include?(method_name.to_sym)
        return { error: 'action not available' }
      end

      result = instance.public_send(method_name.to_sym, payload)
      { success: true, result: result }
    rescue => e
      { error: "execution failed: #{e.message}" }
    end

    def default_log(msg)
      $stderr.puts "[MessageConsumer] #{msg}"
    end
  end

  class DynamicDispatcher
    def initialize(consumer, role_provider)
      @consumer = consumer
      @role_provider = role_provider
    end

    def dispatch(raw_message, user_context)
      role = @role_provider.call(user_context)
      ac = AccessControl.new(role)
      @consumer.process(raw_message, ac)
    end
  end
end

